import { delegate, type SafeHtml } from 'kerfjs';
import { DialogHeader } from '@kerfjs/ui/dialog-header';
import { EmptyState } from '@kerfjs/ui/empty-state';
import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/webawesome.css';
import '@awesome.me/webawesome/dist/components/dialog/dialog.js';
import '@awesome.me/webawesome/dist/components/button/button.js';
import './command-palette.css';

// Catalog review: there is no CommandPalette export or complete palette recipe.
// wa-dialog supplies modal behavior; ordinary input and native command buttons
// have the right semantics. MenuItem is a navigation row, Select chooses values,
// and TokenSearchField is a structured editor, so none is a palette substitute.
export interface Command { id: string; label: string; group: string; keywords?: string; disabled?: boolean }
interface DialogElement extends HTMLElement { open: boolean }
export function mountCommandPalette(root: HTMLElement, app: {
  id: string;
  commands: Command[];
  run(id: string): void;
  recentIds(): string[];
  saveRecentIds(ids: string[]): void;
  renderInto(root: HTMLElement, view: SafeHtml): void;
}) {
  let query = '';
  let open = false;
  let invoker: HTMLElement | null = null;
  let recent = app.recentIds().filter(id => app.commands.some(command => command.id === id)).slice(0, 8);
  const titleId = app.id + '-title';
  const summaryId = app.id + '-summary';
  const resultId = app.id + '-results';
  const inputId = app.id + '-query';
  const dialog = () => root.querySelector<DialogElement>('wa-dialog')!;
  const input = () => root.querySelector<HTMLInputElement>('[data-command-query]')!;
  function groups() {
    const needle = query.trim().toLocaleLowerCase();
    const matched = app.commands.filter(command => (command.label + ' ' + (command.keywords ?? '')).toLocaleLowerCase().includes(needle));
    const buckets = new Map<string, Command[]>();
    const recentCommands = needle ? [] : recent.map(id => matched.find(command => command.id === id)).filter((command): command is Command => !!command);
    if (recentCommands.length) buckets.set('Recent commands', recentCommands);
    for (const command of matched) {
      if (recentCommands.some(item => item.id === command.id)) continue;
      const group = buckets.get(command.group) ?? [];
      group.push(command); buckets.set(command.group, group);
    }
    return [...buckets.entries()];
  }
  const results = () => {
    const grouped = groups();
    return <div class="kui-section-stack">
      {grouped.length ? grouped.map(([label, commands], index) => <section aria-labelledby={app.id + '-group-' + index}>
        <h3 id={app.id + '-group-' + index}>{label}</h3>
        <ul class="command-list">{commands.map(command => <li>
          <button class="command-option" type="button" data-action="commands.run" data-command-id={command.id} disabled={command.disabled}>
            {command.label}{command.disabled && <span> — Unavailable</span>}
          </button>
        </li>)}</ul>
      </section>) : <EmptyState title="No matching commands" detail="Try another word or clear the search." />}
    </div>;
  };
  function renderResults() {
    app.renderInto(root.querySelector<HTMLElement>('[data-command-results]')!, results());
    root.querySelector<HTMLElement>('[data-command-count]')!.textContent =
      groups().reduce((total, [, commands]) => total + commands.length, 0) + ' commands found';
  }
  app.renderInto(root, <div class="palette-root kui-layout">
    <button type="button" data-action="commands.show">Commands</button>
    <wa-dialog class="command-dialog" label="Commands" without-header open={open} aria-labelledby={titleId} aria-describedby={summaryId}>
      <DialogHeader title="Commands" titleId={titleId} summary="Find and run a workspace command." summaryId={summaryId} />
      <div class="kui-dialog-body kui-section-stack">
        <label for={inputId}>Search commands</label>
        <input id={inputId} class="command-query" type="search" data-command-query="true" autocomplete="off" aria-controls={resultId} aria-describedby={app.id + '-keys'} />
        <p id={app.id + '-keys'}>Use Down Arrow to reach results, Up and Down to move, and Enter to run. Escape closes.</p>
        <p role="status" aria-live="polite" data-command-count="true"></p>
        <div id={resultId} data-command-results="true">{results()}</div>
      </div>
      <wa-button slot="footer" appearance="outlined" data-action="commands.close">Close</wa-button>
    </wa-dialog>
  </div>);
  const disposers = [
    delegate(root, 'input', '[data-command-query]', (_event, element) => {
      query = (element as HTMLInputElement).value; renderResults();
    }),
    delegate(root, 'click', '[data-action]', (_event, element) => {
      const node = element as HTMLElement;
      if (node.dataset.action === 'commands.show') {
        invoker = node; open = true; query = ''; input().value = '';
        renderResults(); dialog().open = true;
      } else if (node.dataset.action === 'commands.close') dialog().open = false;
      else if (node.dataset.action === 'commands.run') {
        const command = app.commands.find(item => item.id === node.dataset.commandId);
        if (!command || command.disabled) return;
        recent = [command.id, ...recent.filter(id => id !== command.id)].slice(0, 8);
        app.saveRecentIds(recent);
        dialog().open = false;
        app.run(command.id);
      }
    }),
    delegate(root, 'keydown', '[data-command-query], [data-command-id]', (event, element) => {
      const key = event as KeyboardEvent;
      if (key.isComposing) return;
      const buttons = Array.from(root.querySelectorAll<HTMLButtonElement>('[data-command-id]:not(:disabled)'));
      if (!buttons.length) return;
      const atInput = element.matches('[data-command-query]');
      const index = buttons.indexOf(element as HTMLButtonElement);
      let next: number | null = null;
      if (key.key === 'ArrowDown') next = atInput ? 0 : (index + 1) % buttons.length;
      if (key.key === 'ArrowUp') {
        if (!atInput && index === 0) { key.preventDefault(); input().focus(); return; }
        next = atInput ? buttons.length - 1 : index - 1;
      }
      if (!atInput && key.key === 'Home') next = 0;
      if (!atInput && key.key === 'End') next = buttons.length - 1;
      if (atInput && key.key === 'Enter') { key.preventDefault(); buttons[0]?.click(); return; }
      if (next !== null) { key.preventDefault(); buttons[next]?.focus(); buttons[next]?.scrollIntoView({ block: 'nearest' }); }
      // Native buttons retain Tab, Enter and Space. No incomplete menu/listbox roles.
    }),
  ];
  const afterShow = (event: Event) => { if (event.target === dialog()) input().focus(); };
  const afterHide = (event: Event) => {
    if (event.target !== dialog()) return;
    open = false;
    if (invoker?.isConnected) invoker.focus();
  };
  root.addEventListener('wa-after-show', afterShow);
  root.addEventListener('wa-after-hide', afterHide);
  return () => {
    disposers.forEach(dispose => dispose());
    root.removeEventListener('wa-after-show', afterShow);
    root.removeEventListener('wa-after-hide', afterHide);
  };
}

