.command-dialog { --spacing: 0; --width: min(40rem, calc(100vw - 2 * var(--kui-layout-dialog-inset))); }
.command-list { margin: 0; padding: 0; list-style: none; display: grid; gap: var(--kui-layout-control-gap); }
.command-query, .command-option { box-sizing: border-box; width: 100%; min-height: 2.5rem; font: inherit; color: var(--kui-color-text); background: var(--kui-color-surface); border: 1px solid var(--kui-color-border); border-radius: var(--kui-radius-m); padding: var(--kui-space-xs) var(--kui-space-s); }
.command-option { text-align: start; overflow-wrap: anywhere; }
.command-option:hover:not(:disabled) { background: var(--kui-color-neutral-fill-quiet); }
.command-option:disabled { color: var(--kui-color-text-quiet); }
.command-query:focus-visible, .command-option:focus-visible { outline: var(--kui-focus-ring); outline-offset: 2px; }
/* The production modal body owns scrolling; results add no nested scroll area. */
